with deduped as (select id, ends_on, discount_pct from promotions qualify row_number() over (partition by promo_code order by ends_on desc, id) = 1) select date_trunc('year', ends_on) as year_start, sum(discount_pct) as total_discount_pct, percentile_approx(discount_pct, array(0.25, 0.5, 0.75)) as discount_pct_quartiles from deduped group by 1 having sum(discount_pct) > 0 order by year_start desc
